import { expect, expectStatus, test, uniqueName } from "../../fixtures";
import type { APIRequestContext } from "../../fixtures";

const TAG = "@REV-07";

type Vendor = { id: string; status: string };
type Doc = { id: string; kind: string; status: string };
type Extraction = { id: string; status: string };

async function uploadDocument(member: APIRequestContext, vendorId: string, kind: string, filename: string): Promise<Doc> {
  const response = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: { name: filename, mimeType: "application/pdf", buffer: Buffer.from("%PDF-1.4 fixture") },
    },
  });
  return expectStatus<Doc>(response, 201);
}

async function waitForExtraction(member: APIRequestContext, documentId: string): Promise<void> {
  await expect
    .poll(
      async () => (await expectStatus<Doc>(await member.get(`/api/documents/${documentId}`), 200)).status,
      { timeout: 60_000 },
    )
    .toBe("extracted");
}

test.describe("review vendors", () => {
  test("an expired insurance certificate cannot be approved", { tag: TAG }, async ({ apiAs }) => {
    // Arrange: a vendor in review whose insurance certificate is the expired fixture (expired yesterday).
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");

    const vendor = await expectStatus<Vendor>(
      await member.post("/api/vendors", {
        data: {
          name: uniqueName("Expired COI Vendor"),
          category: "services",
          contact_email: `rev07-${Date.now()}-${Math.floor(Math.random() * 1e6)}@example.test`,
        },
      }),
      201,
    );

    const w9 = await uploadDocument(member, vendor.id, "w9", "w9.pdf");
    const insurance = await uploadDocument(member, vendor.id, "insurance_certificate", "insurance-expired.pdf");
    const contract = await uploadDocument(member, vendor.id, "contract", "contract.pdf");

    await waitForExtraction(member, w9.id);
    await waitForExtraction(member, insurance.id);
    await waitForExtraction(member, contract.id);

    const submitted = await expectStatus<Vendor>(
      await member.post(`/api/vendors/${vendor.id}/submit`),
      200,
    );
    expect(submitted.status).toBe("in_review");

    const insuranceExtraction = await expectStatus<Extraction>(
      await reviewer.get(`/api/documents/${insurance.id}/extraction`),
      200,
    );
    expect(insuranceExtraction.status).toBe("pending_review");

    // Act: reviewer tries to approve the expired insurance certificate extraction.
    const response = await reviewer.post(`/api/extractions/${insuranceExtraction.id}/decision`, {
      data: { decision: "approve" },
    });

    // Assert
    const body = await expectStatus<{ error: { code: string } }>(response, 409);
    expect(body.error.code).toBe("insurance_expired");

    // The extraction must remain unapproved.
    const after = await expectStatus<Extraction>(
      await reviewer.get(`/api/documents/${insurance.id}/extraction`),
      200,
    );
    expect(after.status).toBe("pending_review");
  });
});
